# Generated by build.py from recipe.yml for recipe http-download-in-parallel-segments. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'slow-site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'fetch-in-segments.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Fetches <url> as <n> byte ranges at once with one curl command, joins the segments in`n# order into joined, and compares the result with <original>.`n# Usage: sh fetch-in-segments.sh <url> <n> <original>`nurl=`$1; n=`$2; original=`$3`n`n# The size, from a HEAD request, and the segment length, rounded up.`nsize=`$(curl -s -f -I -o /dev/null -w `"%header{content-length}`" `"`$url`") || exit`nseg=`$(( (size + n - 1) / n ))`n`n# One transfer per segment, separated by --next; the last segment stops at the last byte.`nset --`ni=0`nwhile [ `"`$i`" -lt `"`$n`" ]; do`n  first=`$(( i * seg )); last=`$(( first + seg - 1 ))`n  [ `"`$last`" -lt `"`$size`" ] || last=`$(( size - 1 ))`n  [ `"`$i`" -eq 0 ] || set -- `"`$@`" --next`n  set -- `"`$@`" -s -f -r `"`$first-`$last`" -o `"segment`$i`" -w `"%{http_code} %header{content-range}\n`" `"`$url`"`n  i=`$(( i + 1 ))`ndone`ncurl --parallel --parallel-immediate `"`$@`" > segments.txt || exit`nsort -k3n segments.txt`n`n# Join in segment order, not in the order the transfers ended, then compare byte for byte.`n: > joined`ni=0`nwhile [ `"`$i`" -lt `"`$n`" ]; do cat `"segment`$i`" >> joined; i=`$(( i + 1 )); done`necho `"joined: `$(wc -c < joined | tr -d ' ') bytes`"`nif cmp -s joined `"`$original`"; then echo `"identical`"; else echo `"differs`"; exit 1; fi`n")
[IO.File]::WriteAllText((Join-Path $PWD 'seen-by-server.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Reads a surl -v log: the Range headers surl received, the 206 answers it gave, and how`n# many connections (exchange numbers) carried them.`n# Usage: sh seen-by-server.sh <log>`n# surl writes its log a moment after curl is done: wait until every exchange it opened has ended, 10 s at most.`ni=0; until [ `"`$(grep -c '\* Exchange [0-9]* opened' `"`$1`")`" = `"`$(grep -c '\* Exchange [0-9]* ended' `"`$1`")`" ]; do i=`$((i+1)); [ `$i -ge 100 ] && break; sleep 0.1; done`ngrep '< Range: ' `"`$1`" | sed -e 's/^#[0-9]* < //' -e 's/\\r\\n`$//' | sort -t '=' -k2n`necho `"answered 206: `$(grep -c '\* GET /big.bin: 206' `"`$1`")`"`necho `"connections: `$(grep '\* GET /big.bin: 206' `"`$1`" | cut -d' ' -f1 | sort -u | wc -l | tr -d ' ')`"`n")
cmd /c 'head -c 1000000 /dev/urandom > site/big.bin'
cmd /c 'cp site/big.bin slow-site/big.bin'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh fetch-in-segments.sh http://127.0.0.1:8080/big.bin 4 site/big.bin } finally { Stop-Process $server0 }
